520:  * Test that clicking on various elements in the attachment bar toggles the
521:  * attachment list.
522:  *
523:  * @param {string} elementId - The id of the element to click.
524:  */
525: function subtest_attachment_list_toggle(elementId) {
526:   const aboutMessage = get_about_message();
527:   const attachmentList = aboutMessage.document.getElementById("attachmentList");
528:   const element = aboutMessage.document.getElementById(elementId);
529: 
530:   EventUtils.synthesizeMouseAtCenter(element, { clickCount: 1 }, aboutMessage);
