532:     !attachmentList.collapsed,
533:     `Attachment list should be expanded after clicking ${elementId}!`
534:   );
535:   assert_attachment_list_focused();
536: 
537:   EventUtils.synthesizeMouseAtCenter(element, { clickCount: 1 }, aboutMessage);
